"""Explicit, public, task-specific bindings for the original ten-role pool.

A binding is a reviewed input to an episode, never generated by its simulator.
Source excerpts and execution receipts are retained verbatim. Missing fixtures
remain unbound; registering a role is not evidence of task applicability.
"""
import json
from pathlib import Path, PurePosixPath

from registry import Candidate, harness_trigger, load_persona
from support import digest, file_hash, read

VERSION = "swe-task-binding-v1"


def safe_relative(value):
    path = PurePosixPath(value)
    if (not value or path.is_absolute() or ".." in path.parts or "\\" in value
            or ":" in value or str(path) != value):
        raise ValueError("Expected a normalized relative artifact path")
    return value


def load_binding(path, manifest, persona_id):
    path = Path(path).resolve()
    bound = read(path)
    persona = load_persona(persona_id)
    if (bound.get("version") != VERSION or bound.get("persona") != persona_id
            or bound.get("instance_id") != manifest.task_id
            or bound.get("base_commit") != manifest.base_commit
            or bound.get("public_instruction_digest") != digest(manifest.instruction)
            or bound.get("persona_digest") != digest(persona)):
        raise ValueError("Binding identity does not match the frozen public task and pool")
    template = next((t for t in persona["attributes"]["evolved_requirements"]
                     if t["id"] == bound.get("template_id")), None)
    if template is None or set(bound.get("slots", {})) != set(template["bindings"]):
        raise ValueError("Binding must fill exactly the selected pool template's slots")
    if any(not isinstance(v, str) or not v.strip() or "{{" in v for v in bound["slots"].values()):
        raise ValueError("Unresolved or empty template binding")
    if not bound.get("initial_notice") or not bound.get("fixture_kind"):
        raise ValueError("Missing initial persona/environment facts or fixture implementation")
    facts = bound.get("public_facts", [])
    if not facts or any(not f.get("quote") or f["quote"] not in manifest.instruction for f in facts):
        raise ValueError("Applicability must cite exact excerpts from the public issue")
    evidence = bound.get("evidence", [])
    if not evidence:
        raise ValueError("No baseline/fixture evidence")
    if bound.get('public_evidence') and bound['public_evidence'] not in {e['path'] for e in evidence}:
        raise ValueError('Public evidence must be an immutable allowlisted artifact')
    for item in evidence:
        relative = safe_relative(item["path"])
        artifact = (path.parent / relative).resolve()
        if path.parent not in artifact.parents or not artifact.is_file():
            raise ValueError("Missing or escaping binding artifact")
        if file_hash(artifact) != item["sha256"]:
            raise ValueError("Binding evidence changed: " + relative)
        if item.get("kind") not in ("baseline_source", "public_fixture", "execution_receipt"):
            raise ValueError("Unrecognized evidence provenance")
        manifest.assert_no_leak(artifact.read_text(encoding="utf-8"), "binding evidence")
    from task_fixtures import specification
    spec = specification(bound["fixture_kind"], persona_id, template["id"])
    expected = {name: file_hash(Path(__file__).parent / "fixtures" / name) for name in spec["fixture_sources"]}
    receipts = [read(path.parent / item["path"]) for item in evidence if item["kind"] == "execution_receipt"]
    if not any(receipt.get("sources") == expected for receipt in receipts):
        raise ValueError("Fixture implementation changed or executed-source provenance missing; revalidate the fixture")
    manifest.assert_no_leak(json.dumps(bound, ensure_ascii=False), "task binding")
    return bound


def candidate_for(bound):
    persona = load_persona(bound["persona"])
    template = next(t for t in persona["attributes"]["evolved_requirements"]
                    if t["id"] == bound["template_id"])
    # The fixture registry decides how to measure a template. JSON cannot name
    # an arbitrary command or downgrade a trusted-harness requirement to style.
    from task_fixtures import specification
    spec = specification(bound["fixture_kind"], persona["id"], template["id"])
    if bound["instance_id"] not in spec["instance_ids"]:
        raise ValueError("Fixture is not registered for this task")
    requirement = "req." + template["id"] + ".01"
    checker = {"id": "task_fixture", "version": "1", "parameters": {"binding": digest(bound)}}
    if template["satisfaction"]["judge"] != "trusted_harness":
        checker = {"id": "rubric_judge", "version": "1", "parameters": {
            "requirement": requirement + "@1", "samples": 3,
            "message_clauses": spec["message_clauses"], "subcheck": checker}}
    candidate = Candidate(
        candidate_id="cand-" + template["id"], requirement_id=requirement,
        persona_id=persona["id"], template_id=template["id"], template=template,
        bindings=dict(bound["slots"]), checker=checker,
        schedule={"trigger_event": harness_trigger(template), "earliest_turn": 2,
                  "deadline_turn": 4, "priority": 1, "required": True},
        disclosure_markers=spec["disclosure_markers"],
        contract_compat="Public task and original official tests remain frozen; " + spec["contract_compat"],
        evidence_refs=["public:original_instruction", "harness-observed/task_binding.json"] +
                      ["harness-observed/binding-evidence/" + e["path"] for e in bound["evidence"]])
    return persona, candidate


def evidence_files(binding_path):
    """Host-owned copies, exposed to the checker rather than read from agent files."""
    binding_path = Path(binding_path)
    bound = read(binding_path)
    files = [{"path": "harness-observed/task_binding.json", "text": binding_path.read_text(encoding="utf-8"),
              "sha256": file_hash(binding_path), "truncated": False}]
    for item in bound["evidence"]:
        source = binding_path.parent / safe_relative(item["path"])
        text = source.read_text(encoding="utf-8")
        # Oversized evidence needs author-selected excerpts with full-file hashes,
        # not silent truncation that could turn missing context into a verdict.
        if len(text) > 60000:
            raise ValueError("Binding evidence exceeds checker context: " + item["path"])
        files.append({"path": "harness-observed/binding-evidence/" + item["path"],
                      "text": text, "sha256": file_hash(source), "truncated": False})
    return files
